package blockchain.contracts

import scala.collection.mutable
import java.time.Instant
import java.security.MessageDigest

object ContractValidator {
  // Rate limiting configuration
  private val MAX_REQUESTS_PER_WINDOW = 100
  private val WINDOW_SIZE_MS = 60000L
  private val MAX_RETRIES = 3
  private val RETRY_BACKOFF_MS = 500L

  // Maximum input lengths to prevent abuse
  private val MAX_METADATA_LENGTH = 1024
  private val MAX_MEMO_LENGTH = 512
  private val MAX_SIGNATURE_LENGTH = 256
  private val MAX_ANNOTATION_LENGTH = 256

  // Request tracking for rate limiting
  private val requestLog = mutable.Map[String, mutable.Queue[(Long, Int)]]() 

  // Lock guarding all access to the shared mutable rate-limit state to
  // prevent race conditions that could corrupt state or bypass limits.
  private val rateLimitLock = new AnyRef

  case class ValidationResult(valid: Boolean, errors: List[String])
  case class ContractSubmission(
    address: String,
    metadata: String,
    abiSignatures: List[String],
    annotations: List[String],
    memo: String,
    submitterKey: String
  )

  def isRateLimited(submitterKey: String): Boolean = rateLimitLock.synchronized {
    val now = System.currentTimeMillis()
    val queue = requestLog.getOrElseUpdate(submitterKey, mutable.Queue.empty)

    // Purge old entries
    while (queue.nonEmpty && queue.front._1 < now - WINDOW_SIZE_MS) {
      queue.dequeue()
    }

    val totalRequests = queue.map(_._2).sum
    totalRequests >= MAX_REQUESTS_PER_WINDOW
  }

  def recordRequest(submitterKey: String, weight: Int = 1): Unit = rateLimitLock.synchronized {
    val now = System.currentTimeMillis()
    val queue = requestLog.getOrElseUpdate(submitterKey, mutable.Queue.empty)
    queue.enqueue((now, weight))
  }

  def computeHash(data: String): String = {
    val digest = MessageDigest.getInstance("SHA-256")
    digest.digest(data.getBytes("UTF-8")).map("%02x".format(_)).mkString
  }

  // Safe validation using character-by-character parsing instead of regex
  private def isValidAddress(addr: String): Boolean = {
    addr.length == 42 &&
    addr.startsWith("0x") &&
    addr.drop(2).forall(c => (c >= '0' && c <= '9') || (c >= 'a' && c <= 'f') || (c >= 'A' && c <= 'F'))
  }

  // Parse metadata as key=value pairs separated by semicolons
  private def isValidMetadata(meta: String): Boolean = {
    if (meta.length > MAX_METADATA_LENGTH) return false
    val pairs = meta.split(';')
    pairs.forall { pair =>
      val trimmed = pair.trim
      val eqIdx = trimmed.indexOf('=')
      if (eqIdx <= 0) false
      else {
        val key = trimmed.substring(0, eqIdx).trim
        key.nonEmpty && key.head.isLetter && key.forall(c => c.isLetterOrDigit || c == '_')
      }
    }
  }

  // Validate ABI signature format: name(types) -> returnType
  private def isValidAbiSignature(sig: String): Boolean = {
    if (sig.length > MAX_SIGNATURE_LENGTH) return false
    val arrowIdx = sig.indexOf("->")
    if (arrowIdx < 0) return false
    val beforeArrow = sig.substring(0, arrowIdx).trim
    val afterArrow = sig.substring(arrowIdx + 2).trim

    val parenOpen = beforeArrow.indexOf('(')
    val parenClose = beforeArrow.lastIndexOf(')')
    if (parenOpen < 1 || parenClose != beforeArrow.length - 1) return false

    val funcName = beforeArrow.substring(0, parenOpen)
    funcName.nonEmpty && funcName.head.isLetter && funcName.forall(c => c.isLetterOrDigit || c == '_') &&
    afterArrow.nonEmpty && afterArrow.forall(c => c.isLetterOrDigit || c == '[' || c == ']')
  }

  // Validate annotation format: @name(params)
  private def isValidAnnotation(annot: String): Boolean = {
    if (annot.length > MAX_ANNOTATION_LENGTH) return false
    if (!annot.startsWith("@")) return false
    val parenOpen = annot.indexOf('(')
    val parenClose = annot.lastIndexOf(')')
    if (parenOpen < 2 || parenClose != annot.length - 1) return false

    val name = annot.substring(1, parenOpen)
    name.nonEmpty && name.head.isLetter && name.forall(c => c.isLetterOrDigit || c == '_')
  }

  // Validate memo - simple text with optional XML-like tags (no nesting)
  private def isValidMemo(memo: String): Boolean = {
    if (memo.length > MAX_MEMO_LENGTH) return false
    // Simple state machine: just ensure tags are balanced at top level
    var i = 0
    var depth = 0
    while (i < memo.length) {
      if (memo(i) == '<') {
        if (i + 1 < memo.length && memo(i + 1) == '/') {
          depth -= 1
          if (depth < 0) return false
        } else {
          depth += 1
        }
        // Skip to closing >
        val closeIdx = memo.indexOf('>', i)
        if (closeIdx < 0) return false
        i = closeIdx + 1
      } else {
        i += 1
      }
    }
    depth == 0
  }

  def validateWithRetry(submission: ContractSubmission, attempt: Int = 0): ValidationResult = {
    if (isRateLimited(submission.submitterKey)) {
      if (attempt < MAX_RETRIES) {
        Thread.sleep(RETRY_BACKOFF_MS * (attempt + 1))
        return validateWithRetry(submission, attempt + 1)
      }
      return ValidationResult(false, List("Rate limit exceeded after retries"))
    }

    recordRequest(submission.submitterKey, weight = 2)
    performValidation(submission)
  }

  def performValidation(submission: ContractSubmission): ValidationResult = {
    val errors = mutable.ListBuffer[String]()

    // Validate address format
    if (!isValidAddress(submission.address)) {
      errors += s"Invalid contract address: ${submission.address.take(10)}..."
    }

    // Validate metadata
    if (submission.metadata.nonEmpty) {
      if (!isValidMetadata(submission.metadata)) {
        errors += "Invalid metadata format"
      }
    }

    // Validate ABI signatures
    submission.abiSignatures.zipWithIndex.foreach { case (sig, idx) =>
      if (!isValidAbiSignature(sig)) {
        errors += s"Invalid ABI signature at index $idx"
      }
    }

    // Validate annotations
    submission.annotations.foreach { annot =>
      if (!isValidAnnotation(annot)) {
        errors += s"Invalid annotation: ${annot.take(20)}..."
      }
    }

    // Validate memo field
    if (submission.memo.nonEmpty) {
      if (!isValidMemo(submission.memo)) {
        errors += "Invalid memo format"
      }
    }

    // Compute submission hash for audit trail
    val submissionData = s"${submission.address}|${submission.metadata}|${submission.memo}"
    val hash = computeHash(submissionData)

    if (errors.isEmpty) {
      ValidationResult(true, List.empty)
    } else {
      ValidationResult(false, errors.toList)
    }
  }
}
